      flex-shrink: 0;
    }

    .status-delivered {
      background: var(--delivered-bg);
      color: var(--delivered-text);
    }

    .status-shipping {
      background: var(--shipping-bg);
      color: var(--shipping-text);
    }

    .status-cancelled {
      background: var(--cancelled-bg);
      color: var(--cancelled-text);
    }

    .order-details {
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-bottom: 14px;
    }

    .date-line {
      font-size: 14px;
      color: var(--text-primary);
      display: flex;
      align-items: center;
      gap: 6px;
      flex-wrap: wrap;
    }

    .date-separator {
      color: var(--text-secondary);
      font-size: 10px;
    }

    .items-line {
      font-size: 13px;
      color: var(--text-secondary);
    }

    .order-total {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 12px;
      border-top: 1px solid var(--border);
    }

    .total-label {
      font-size: 13px;
      color: var(--text-secondary);
    }

    .total-amount {
      font-size: 16px;
      font-weight: 600;
      color: var(--text-primary);
